import{_ as m,l as o,o as t,c as l,v as e,p as n,x as r,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"几何布朗运动","description":"","frontmatter":{"title":"几何布朗运动","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/geometric-brownian-motion.md","filePath":"quant/geometric-brownian-motion.md","lastUpdated":1789023840000}'),c={name:"quant/geometric-brownian-motion.md"};function u(E,a,S,_,p,B){const i=o("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="几何布朗运动" tabindex="-1">几何布朗运动 <a class="header-anchor" href="#几何布朗运动" aria-label="Permalink to &quot;几何布朗运动&quot;">​</a></h1><div class="epigraph"><p>股价取几何布朗运动：$\\mathrm d S_t=\\mu S_t\\,\\mathrm d t+\\sigma S_t\\,\\mathrm d W_t$，解是对数正态，正性由指数自动保证。</p><footer>—— 据 Black and Scholes, J. Political Economy, 1973；Merton, Bell Journal of Economics, 1973；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/sde-meaning">随机微分方程的含义</a>把 SDE 读成积分方程。缺口是金融主干上最常用的那一条：价格要正、冲击按比例、还要能显式解出。算术布朗运动可取负，Bachelier 的模型在这里不够。本课只解 GBM，并把 \\(\\tfrac12\\sigma^2\\) 修正钉死；期权公式、风险中性替换 \\(\\mu\\mapsto r\\) 都还没出场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价格水平 \\(S\\) 若走 \\(\\mathrm d S=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\)，下一时刻可以穿过零。收益率按比例冲击更自然：同样大小的 \\(\\mathrm d W\\)，高价股票对应更大的绝对变动。缺口是写出线性乘性系数的 SDE，并用<a href="/quant/ito-lemma">伊藤引理</a>解出来，而不是把「对数正态」当成分布假设另起炉灶。</p><p>显式解还要回答：\\(\\mathbb E[S_t]\\) 的增长率是 \\(\\mu\\) 还是 \\(\\mu-\\tfrac12\\sigma^2\\)。两者都对，对象不同——一个是 \\(S\\)，一个是 \\(\\ln S\\)。后课换测度、写 Black 公式，会反复踩这块。</p><h3 id="不是风险溢价" tabindex="-1">\\(\\tfrac12\\sigma^2\\) 不是风险溢价 <a class="header-anchor" href="#不是风险溢价" aria-label="Permalink to &quot;$\\tfrac12\\sigma^2$ 不是风险溢价&quot;">​</a></h3><p>对数坐标里的漂移 \\(\\mu-\\tfrac12\\sigma^2\\) 来自 \\(\\ln\\) 的二阶导，是 Itô 修正，不是投资者要求的超额回报。风险溢价是 \\(\\mu-r\\)，要等<a href="/quant/risk-neutral-measure">风险中性测度</a>才出现。把两者说成同一件事，会在贴现期望时把凸性调整和测度变换搅在一起。</p><p><span class="marginnote">Samuelson 1965 建议用 GBM 替代算术布朗，目的就是正性。Black–Scholes 与 Merton 1973 把它写成定价引擎的原生动力学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GBM：\\(\\mathrm d S_t=\\mu S_t\\,\\mathrm d t+\\sigma S_t\\,\\mathrm d W_t\\)，\\(S_0\\gt 0\\)，\\(\\sigma\\) 常数。令 \\(Y=\\ln S\\)，Itô 给出</p> \\[\\mathrm d Y_t=\\bigl(\\mu-\\tfrac12\\sigma^2\\bigr)\\mathrm d t+\\sigma\\,\\mathrm d W_t, \\]<p>故</p> \\[S_t=S_0\\exp\\bigl((\\mu-\\tfrac12\\sigma^2)t+\\sigma W_t\\bigr). \\]<p>\\(S_t\\) 对数正态：\\(\\ln S_t\\sim\\mathcal N(\\ln S_0+(\\mu-\\tfrac12\\sigma^2)t,\\sigma^2 t)\\)。均值 \\(\\mathbb E[S_t]=S_0 e^{\\mu t}\\)。二次变差 \\([S]_t=\\int_0^t\\sigma^2 S_s^2\\,\\mathrm d s\\)。这是强解，轨道唯一。多维时把 \\(W\\) 换成相关布朗、把 \\(\\sigma\\) 换成矩阵，形式相同。</p>',15)),(t(),n(d,null,{default:r(()=>[h(i,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20SDE%5B%22dS%20%E7%AD%89%E4%BA%8E%20mu%20S%20dt%20%E5%8A%A0%20sigma%20S%20dW%22%5D%20--%3E%20LOG%5B%22Y%20%E7%AD%89%E4%BA%8E%20ln%20S%22%5D%0A%20%20LOG%20--%3E%20ITO%5B%22%E4%BC%8A%E8%97%A4%E4%BF%AE%E6%AD%A3%E5%87%8F%E5%8E%BB%E4%BA%8C%E5%88%86%E4%B9%8B%E4%B8%80%20sigma%20%E5%B9%B3%E6%96%B9%22%5D%0A%20%20ITO%20--%3E%20SOL%5B%22%E6%8C%87%E6%95%B0%E8%A7%A3%E3%80%81%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%22%5D%0A%20%20SOL%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%E6%8A%95%E5%BD%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>乘性扩散让相对冲击平稳：\\(\\mathrm d S/S\\) 的系数不依赖 \\(S\\) 的水平。这是后课 Black 公式用远期、用 \\(\\ln(S/K)\\) 的几何来源。指数映射把 \\(\\mathbb R\\) 上的算术布朗送进 \\((0,\\infty)\\)，零是自然边界、达不到（\\(\\sigma\\) 有限时）。\\(\\mu\\) 只出现在漂移，不出现在 \\([S]\\)——波动率输入是 \\(\\sigma\\)，不是 \\(\\mu\\)。真实测度下 \\(\\mu\\) 进入期望增长率；定价改测度后它会被取消，本课先把动力学本身写对。</p><p>离散实现：\\(S_{t+\\Delta}=S_t\\exp((\\mu-\\tfrac12\\sigma^2)\\Delta+\\sigma\\sqrt{\\Delta}Z)\\)，\\(Z\\sim N(0,1)\\)。这是精确转移，不是 Euler 近似。后课蒙特卡洛对 GBM 应走这条，避免 Euler 把正性破坏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导期权价格，不谈波动率微笑，不把 \\(\\sigma\\) 写成随机过程。常数 \\(\\sigma\\) 是强假设，<a href="/quant/vol-as-input">波动率是输入不是输出</a>会回来拆它。本课程是定价数学，不重写限价簿里的价格形成。后课默认：标的在需要闭式或 PDE 时先当作 GBM；真实测度下均值用 \\(e^{\\mu t}\\)，对数漂移带 \\(\\tfrac12\\sigma^2\\)。下一课离开路径，把<a href="/quant/conditional-expectation-proj">条件期望作为投影</a>装进 \\(L^2\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GBM 是乘性漂移与乘性扩散；解为正的对数正态。</li><li>\\(\\ln S\\) 的漂移少 \\(\\tfrac12\\sigma^2\\)，这是 Itô 修正不是风险溢价。</li><li>\\(\\mathbb E[S_t]=S_0 e^{\\mu t}\\)；二次变差由 \\(\\sigma S\\) 决定。</li><li>精确离散用指数映射，不要用会穿零的 Euler。</li><li>出处：Black–Scholes 1973；Merton 1973；Shreve SDE II 第 5 章。</li></ul>',7))])}const A=m(c,[["render",u]]);export{f as __pageData,A as default};
